import { createFileRoute, redirect, useRouter } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useState } from "react";
import { VendorShell } from "~/components/vendor-chrome";
import { fetchVendorMe } from "~/server/vendor-functions";
import { fetchOwnedListing, updateOwnedListing } from "~/server/listing-claim-functions";

export const Route = createFileRoute("/vendor/listing")({
  head: () => ({ meta: [{ title: "Edit directory listing | Shop My Neighborhood" }] }),
  loader: async () => { const me = await fetchVendorMe(); if (!me) throw redirect({ to: "/vendor/login" }); const listing = await fetchOwnedListing(); if (!listing || listing === "unauthenticated") throw redirect({ to: "/vendor/claim" }); return { me, listing }; },
  component: ListingPage,
});
function ListingPage() {
  const { me, listing } = Route.useLoaderData(); const router = useRouter(); const save = useServerFn(updateOwnedListing);
  const [hours, setHours] = useState(listing.opening_hours ?? ""); const [phone, setPhone] = useState(listing.phone ?? ""); const [website, setWebsite] = useState(listing.website ?? ""); const [description, setDescription] = useState(listing.description ?? ""); const [notice, setNotice] = useState<{ ok: boolean; text: string } | null>(null); const [busy, setBusy] = useState(false);
  async function onSubmit(e: React.FormEvent) { e.preventDefault(); setBusy(true); setNotice(null); try { const result = await save({ data: { openingHours: hours, phone, website, description } }); setNotice({ ok: result.ok, text: result.message }); if (result.ok) await router.invalidate(); } catch { setNotice({ ok: false, text: "Your listing could not be updated. Please try again." }); } finally { setBusy(false); } }
  return <VendorShell vendorName={me.businessName} tierLabel={me.tierLabel}><div className="mx-auto max-w-3xl px-4 py-7"><p className="kicker">Claimed business listing</p><h1 className="mt-1 font-display text-3xl font-semibold text-brand-dark">Edit {listing.name}</h1><p className="mt-2 text-sm text-ink-soft">{listing.city_name}, Florida · Your listing name and city come from the directory and cannot be changed here.</p><form onSubmit={onSubmit} className="mt-6 rounded-3xl border border-black/5 bg-white p-5 shadow-sm"><label className="block text-sm font-semibold text-ink">Hours<input value={hours} onChange={(e) => setHours(e.target.value)} maxLength={300} placeholder="Mon–Fri 9am–5pm" className="mt-1.5 w-full rounded-xl border border-black/10 px-3 py-2.5 text-sm font-normal" /></label><label className="mt-4 block text-sm font-semibold text-ink">Phone<input value={phone} onChange={(e) => setPhone(e.target.value)} maxLength={40} placeholder="(352) 555-0100" className="mt-1.5 w-full rounded-xl border border-black/10 px-3 py-2.5 text-sm font-normal" /></label><label className="mt-4 block text-sm font-semibold text-ink">Website<input value={website} onChange={(e) => setWebsite(e.target.value)} maxLength={500} placeholder="https://example.com" className="mt-1.5 w-full rounded-xl border border-black/10 px-3 py-2.5 text-sm font-normal" /></label><label className="mt-4 block text-sm font-semibold text-ink">Short description<textarea value={description} onChange={(e) => setDescription(e.target.value)} maxLength={800} className="mt-1.5 min-h-32 w-full rounded-xl border border-black/10 p-3 text-sm font-normal" placeholder="Tell neighbors what your business offers." /></label>{notice && <p className={`mt-4 rounded-xl px-4 py-3 text-sm ${notice.ok ? "bg-brand-green/15 text-brand-green-dark" : "bg-rose-50 text-rose-900"}`}>{notice.text}</p>}<button disabled={busy} className="mt-5 rounded-full bg-brand px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-60">{busy ? "Saving…" : "Save listing"}</button></form></div></VendorShell>;
}
